package com.fasterxml.jackson.core.json.async;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.async.ByteArrayFeeder;
import com.fasterxml.jackson.core.async.NonBlockingInputFeeder;
import com.fasterxml.jackson.core.io.ByteQuadsCanonicalizer;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.ByteQuadsCanonicalizer;
import com.fasterxml.jackson.core.util.VersionUtil;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NonBlockingJsonParser.feedInput
 */
public class NonBlockingJsonParser_feedInput_TriageGen2Test {

    private NonBlockingJsonParser parser;
    private IOContext ioContext;
    private ByteQuadsCanonicalizer sym;

    @Before
    public void setUp() {
        ioContext = IOContext.bootstrap(null);
        sym = ByteQuadsCanonicalizer.newByteQuadsCanonicalizer();
        parser = new NonBlockingJsonParser(ioContext, 0, sym);
    }

    /**
     * Helper to access private fields via reflection for state verification
     */
    private Object getPrivateField(String fieldName) throws Exception {
        Field field = NonBlockingJsonParser.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(parser);
    }

    /**
     * Helper to set private fields via reflection
     */
    private void setPrivateField(String fieldName, Object value) throws Exception {
        Field field = NonBlockingJsonParser.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(parser, value);
    }

    @Test
    public void testFeedInput_Success() throws Exception {
        byte[] buf = new byte[]{1, 2, 3, 4, 5};
        int start = 1;
        int end = 4;

        // Initial state check (assuming defaults)
        // _inputPtr = 0, _inputEnd = 0, _endOfInput = false, _currInputProcessed = 0, _origBufferLen = 0

        parser.feedInput(buf, start, end);

        assertEquals(buf, getPrivateField("_inputBuffer"));
        assertEquals(start, getPrivateField("_inputPtr"));
        assertEquals(end, getPrivateField("_inputEnd"));
        assertEquals(end - start, getPrivateField("_origBufferLen"));
        assertEquals(0, getPrivateField("_currInputProcessed")); // 0 + 0
        // _currInputRowStart = 1 - (0 - 0) = 1
        assertEquals(1, getPrivateField("_currInputRowStart"));
    }

    @Test(expected = RuntimeException.class)
    public void testFeedInput_Error_RemainingInput() throws Exception {
        // Set up state where there is remaining input
        setPrivateField("_inputPtr", 0);
        setPrivateField("_inputEnd", 5);

        byte[] buf = new byte[10];
        // This should trigger _reportError because _inputPtr < _inputEnd
        parser.feedInput(buf, 0, 5);
    }

    @Test(expected = RuntimeException.class)
    public void testFeedInput_Error_EndBeforeStart() throws Exception {
        setPrivateField("_inputPtr", 0);
        setPrivateField("_inputEnd", 0);
        setPrivateField("_endOfInput", false);

        byte[] buf = new byte[10];
        // end < start
        parser.feedInput(buf, 5, 2);
    }

    @Test(expected = RuntimeException.class)
    public void testFeedInput_Error_AlreadyClosed() throws Exception {
        setPrivateField("_inputPtr", 0);
        setPrivateField("_inputEnd", 0);
        setPrivateField("_endOfInput", true);

        byte[] buf = new byte[10];
        parser.feedInput(buf, 0, 5);
    }

    @Test
    public void testFeedInput_UpdatePointersAndRowStart() throws Exception {
        // Simulate a previous call to check accumulation
        setPrivateField("_inputPtr", 0);
        setPrivateField("_inputEnd", 0);
        setPrivateField("_origBufferLen", 10);
        setPrivateField("_currInputProcessed", 20);
        setPrivateField("_currInputRowStart", 5);

        byte[] buf = new byte[20];
        int start = 5;
        int end = 15;

        parser.feedInput(buf, start, end);

        // _currInputProcessed += _origBufferLen => 20 + 10 = 30
        assertEquals(30, getPrivateField("_currInputProcessed"));

        // _currInputRowStart = start - (_inputEnd - _currInputRowStart)
        // Note: in the method, _inputEnd and _currInputRowStart used are the OLD ones before update
        // _inputEnd was 0, _currInputRowStart was 5
        // start = 5. Calculation: 5 - (0 - 5) = 10
        assertEquals(10, getPrivateField("_currInputRowStart"));

        assertEquals(10, getPrivateField("_origBufferLen"));
        assertEquals(5, getPrivateField("_inputPtr"));
        assertEquals(15, getPrivateField("_inputEnd"));
    }

    @Test
    public void testFeedInput_ZeroLengthBuffer() throws Exception {
        setPrivateField("_inputPtr", 0);
        setPrivateField("_inputEnd", 0);
        setPrivateField("_endOfInput", false);
        setPrivateField("_currInputProcessed", 0);
        setPrivateField("_origBufferLen", 0);
        setPrivateField("_currInputRowStart", 0);

        byte[] buf = new byte[5];
        parser.feedInput(buf, 2, 2);

        assertEquals(2, getPrivateField("_inputPtr"));
        assertEquals(2, getPrivateField("_inputEnd"));
        assertEquals(0, getPrivateField("_origBufferLen"));
        assertEquals(2, getPrivateField("_currInputRowStart")); // 2 - (0 - 0)
    }
}
